-- Demo catalog for local acceptance testing only. Safe to run more than once.
-- This only inserts missing rows; it does not overwrite an existing business catalog.
begin;

do $demo_seed$
declare
  v_business_id uuid;
begin
  select id into v_business_id
  from public.businesses
  where slug = 'tu-balneario-del-mar' and is_active;

  if v_business_id is null then
    raise exception 'Active business tu-balneario-del-mar was not found.';
  end if;

  insert into public.categories (business_id, id, name, emoji, icon_name, sort_order)
  select v_business_id, seed.id, seed.name, seed.emoji, seed.icon_name, seed.sort_order
  from jsonb_to_recordset('[{"id":"cat-burgers","name":"Burgers & Sandwiches","emoji":"🍔","icon_name":"sandwich","sort_order":1},{"id":"cat-rabas","name":"Rabas & Mariscos","emoji":"🦑","icon_name":"fish","sort_order":2},{"id":"cat-pizzas","name":"Pizzas & Empanadas","emoji":"🍕","icon_name":"pizza","sort_order":3},{"id":"cat-papas","name":"Guarniciones & Papas","emoji":"🍟","icon_name":"french-fries","sort_order":4},{"id":"cat-ensaladas","name":"Ensaladas Frescas","emoji":"🥗","icon_name":"salad","sort_order":5},{"id":"cat-cervezas","name":"Cervezas & Chopp","emoji":"🍺","icon_name":"beer","sort_order":6},{"id":"cat-tragos","name":"Tragos & Cocktails","emoji":"🍹","icon_name":"cocktail","sort_order":7},{"id":"cat-bebidas","name":"Licuados & Bebidas","emoji":"🥤","icon_name":"cup-soda","sort_order":8},{"id":"cat-postres","name":"Cafetería & Postres","emoji":"🍨","icon_name":"ice-cream","sort_order":9}]'::jsonb) as seed(id text, name text, emoji text, icon_name text, sort_order integer)
  on conflict (business_id, id) do nothing;

  insert into public.sectors (business_id, id, name, description, type, capacity_summary)
  select v_business_id, seed.id, seed.name, seed.description, seed.type, seed.capacity_summary
  from jsonb_to_recordset('[{"id":"sec-carpas-vip","name":"Sector Carpas VIP","description":"Primera línea con vista al mar directo, reposeras de teca y mesa privada","type":"carpa","capacity_summary":"15 Carpas exclusivas"},{"id":"sec-carpas-familiares","name":"Sector Carpas Familiares","description":"Cerca del área infantil y bajada a la playa, espacio para 6 personas","type":"carpa","capacity_summary":"20 Carpas"},{"id":"sec-sombrillas","name":"Sector Sombrillas & Reposeras","description":"Distribuidas sobre la arena seca con lona cortaviento y mesita de apoyo","type":"sombrilla","capacity_summary":"25 Sombrillas"},{"id":"sec-deck","name":"Deck & Terraza Marina","description":"Mesas exteriores con toldo microperforado sobre tarima de madera","type":"mesa_exterior","capacity_summary":"16 Mesas exteriores"},{"id":"sec-salon","name":"Salón Restaurante Interior","description":"Ambiente climatizado con vista panorámica y atención personalizada","type":"mesa_interior","capacity_summary":"12 Mesas de salón"},{"id":"sec-barra","name":"Barra de Tragos & Playa","description":"Punto de retiro ágil para coctelería, licuados y snacks de paso","type":"mostrador","capacity_summary":"4 Puestos de despacho"}]'::jsonb) as seed(id text, name text, description text, type public.location_type, capacity_summary text)
  on conflict (business_id, id) do nothing;

  insert into public.locations (business_id, id, code, name, type, sector_id, capacity, status, qr_payload, notes)
  select v_business_id, seed.id, seed.code, seed.name, seed.type, seed.sector_id, seed.capacity,
         seed.status, seed.qr_payload, seed.notes
  from jsonb_to_recordset('[{"id":"loc-c01","code":"C-01","name":"Carpa VIP 01","type":"carpa","sector_id":"sec-carpas-vip","capacity":6,"status":"ocupada","qr_payload":"C-01","notes":"Frente al mar"},{"id":"loc-c02","code":"C-02","name":"Carpa VIP 02","type":"carpa","sector_id":"sec-carpas-vip","capacity":6,"status":"disponible","qr_payload":"C-02","notes":"Lista para ocupar"},{"id":"loc-c03","code":"C-03","name":"Carpa VIP 03","type":"carpa","sector_id":"sec-carpas-vip","capacity":6,"status":"ocupada","qr_payload":"C-03","notes":null},{"id":"loc-c04","code":"C-04","name":"Carpa VIP 04","type":"carpa","sector_id":"sec-carpas-vip","capacity":6,"status":"reservada","qr_payload":"C-04","notes":null},{"id":"loc-c05","code":"C-05","name":"Carpa VIP 05","type":"carpa","sector_id":"sec-carpas-vip","capacity":6,"status":"disponible","qr_payload":"C-05","notes":null},{"id":"loc-c06","code":"C-06","name":"Carpa VIP 06","type":"carpa","sector_id":"sec-carpas-vip","capacity":6,"status":"limpieza","qr_payload":"C-06","notes":"Cambio de lonas"},{"id":"loc-s01","code":"S-01","name":"Sombrilla 01","type":"sombrilla","sector_id":"sec-sombrillas","capacity":4,"status":"ocupada","qr_payload":"S-01","notes":null},{"id":"loc-s02","code":"S-02","name":"Sombrilla 02","type":"sombrilla","sector_id":"sec-sombrillas","capacity":4,"status":"disponible","qr_payload":"S-02","notes":null},{"id":"loc-s03","code":"S-03","name":"Sombrilla 03","type":"sombrilla","sector_id":"sec-sombrillas","capacity":4,"status":"ocupada","qr_payload":"S-03","notes":null},{"id":"loc-s04","code":"S-04","name":"Sombrilla 04","type":"sombrilla","sector_id":"sec-sombrillas","capacity":4,"status":"disponible","qr_payload":"S-04","notes":null},{"id":"loc-s12","code":"S-12","name":"Sombrilla 12","type":"sombrilla","sector_id":"sec-sombrillas","capacity":4,"status":"disponible","qr_payload":"S-12","notes":null},{"id":"loc-s15","code":"S-15","name":"Sombrilla 15","type":"sombrilla","sector_id":"sec-sombrillas","capacity":4,"status":"reservada","qr_payload":"S-15","notes":null},{"id":"loc-d01","code":"D-01","name":"Deck Frente al Mar 01","type":"mesa_exterior","sector_id":"sec-deck","capacity":4,"status":"ocupada","qr_payload":"D-01","notes":null},{"id":"loc-d02","code":"D-02","name":"Deck Frente al Mar 02","type":"mesa_exterior","sector_id":"sec-deck","capacity":4,"status":"disponible","qr_payload":"D-02","notes":null},{"id":"loc-d03","code":"D-03","name":"Deck Frente al Mar 03","type":"mesa_exterior","sector_id":"sec-deck","capacity":6,"status":"ocupada","qr_payload":"D-03","notes":null},{"id":"loc-d04","code":"D-04","name":"Deck Frente al Mar 04","type":"mesa_exterior","sector_id":"sec-deck","capacity":2,"status":"disponible","qr_payload":"D-04","notes":null},{"id":"loc-m01","code":"M-01","name":"Mesa Salón 01","type":"mesa_interior","sector_id":"sec-salon","capacity":4,"status":"disponible","qr_payload":"M-01","notes":null},{"id":"loc-m04","code":"M-04","name":"Mesa Salón 04","type":"mesa_interior","sector_id":"sec-salon","capacity":4,"status":"ocupada","qr_payload":"M-04","notes":null},{"id":"loc-m08","code":"M-08","name":"Mesa Salón 08","type":"mesa_interior","sector_id":"sec-salon","capacity":6,"status":"ocupada","qr_payload":"M-08","notes":null},{"id":"loc-m12","code":"M-12","name":"Mesa Salón 12","type":"mesa_interior","sector_id":"sec-salon","capacity":4,"status":"disponible","qr_payload":"M-12","notes":null},{"id":"loc-b01","code":"B-01","name":"Barra Mostrador 01","type":"mostrador","sector_id":"sec-barra","capacity":1,"status":"disponible","qr_payload":"B-01","notes":"Take Away Playa"},{"id":"loc-b02","code":"B-02","name":"Barra Mostrador 02","type":"mostrador","sector_id":"sec-barra","capacity":1,"status":"disponible","qr_payload":"B-02","notes":null}]'::jsonb) as seed(id text, code text, name text, type public.location_type, sector_id text, capacity integer, status public.location_status, qr_payload text, notes text)
  on conflict (business_id, id) do nothing;

  insert into public.products (
    business_id, id, name, description, category_id, price, cost, image, sku,
    is_available, is_active, rating, reviews_count, sales_count, prep_time_minutes,
    tag, is_veggie, is_gluten_free, included_ingredients, removable_ingredients,
    available_addons, variants
  )
  select v_business_id, seed.id, seed.name, seed.description, seed.category_id, seed.price, seed.cost,
         seed.image, seed.sku, seed.is_available, seed.is_active, seed.rating, seed.reviews_count,
         seed.sales_count, seed.prep_time_minutes, seed.tag, seed.is_veggie, seed.is_gluten_free,
         seed.included_ingredients, seed.removable_ingredients, seed.available_addons, seed.variants
  from jsonb_to_recordset('[{"id":"prod-burger-bacon","name":"Doble Bacon Cheddar Burger","description":"Doble medallón de novillo seleccionado (110g c/u), abundante cheddar fundido, panceta laqueada extra crocante y suave pan brioche tostado con manteca clarificada.","category_id":"cat-burgers","price":11800,"cost":4500,"image":"https://images.unsplash.com/photo-1568901346375-23c9450c58cd?auto=format&fit=crop&w=800&q=80","sku":"BUR-01","is_available":true,"is_active":true,"rating":4.9,"reviews_count":342,"sales_count":88,"prep_time_minutes":14,"tag":"MÁS PEDIDO","is_veggie":false,"is_gluten_free":false,"included_ingredients":["Doble medallón novillo","Queso cheddar inglés","Panceta crocante","Pan brioche","Salsa especial"],"removable_ingredients":["Panceta crocante","Salsa especial","Cheddar"],"available_addons":[{"id":"add-cheddar","name":"Extra Cheddar fundido","price":1600},{"id":"add-bacon","name":"Panceta crocante extra","price":1900},{"id":"add-egg","name":"Huevo a la plancha de campo","price":1200},{"id":"add-patty","name":"Medallón de carne adicional (110g)","price":3200}],"variants":[{"id":"v-simple","name":"Simple (1 medallón 150g)","price":9900},{"id":"v-doble","name":"Doble (2 medallones 110g c/u)","price":11800},{"id":"v-triple","name":"Triple Smash Bestial (3 medallones)","price":14600}]},{"id":"prod-burger-smash","name":"Doble Smash Burger Marplatense","description":"Doble medallón 110g smash con costra caramelizada crujiente, queso cheddar fundido, cebolla brunoise finamente picada y salsa secreta de la casa en pan brioche.","category_id":"cat-burgers","price":11500,"cost":4200,"image":"https://images.unsplash.com/photo-1586190848861-99aa4a171e90?auto=format&fit=crop&w=800&q=80","sku":"BUR-02","is_available":true,"is_active":true,"rating":4.8,"reviews_count":290,"sales_count":76,"prep_time_minutes":12,"tag":"POPULAR","is_veggie":false,"is_gluten_free":false,"included_ingredients":["Doble carne smash","Queso cheddar","Cebolla brunoise","Pepinillos","Salsa secreta"],"removable_ingredients":["Cebolla brunoise","Pepinillos","Salsa secreta"],"available_addons":[{"id":"add-cheddar","name":"Extra Cheddar fundido","price":1600},{"id":"add-bacon","name":"Panceta crocante extra","price":1900},{"id":"add-papas","name":"Porción papas fritas bastón","price":2900}],"variants":[]},{"id":"prod-rabas","name":"Rabas Tiernas a la Romana del Parador","description":"Anillas de calamar fresco seleccionado del puerto de Mar del Plata, rebozado crocante dorado, gajos de limón fresco y salsa tártara artesanal.","category_id":"cat-rabas","price":16800,"cost":6500,"image":"https://images.unsplash.com/photo-1599488615731-7e5c2823ff28?auto=format&fit=crop&w=800&q=80","sku":"MAR-01","is_available":true,"is_active":true,"rating":4.9,"reviews_count":412,"sales_count":114,"prep_time_minutes":12,"tag":"ESPECIAL CHEF","is_veggie":false,"is_gluten_free":false,"included_ingredients":["Calamar fresco de puerto","Rebozado criollo","Limón fresco","Salsa tártara"],"removable_ingredients":["Salsa tártara"],"available_addons":[{"id":"add-aioli","name":"Dip de alioli casero al ajo","price":900},{"id":"add-portion","name":"Porción extra abundante (para 3-4)","price":7900}],"variants":[]},{"id":"prod-cornalitos","name":"Cornalitos Dorados del Puerto","description":"Pescaditos cornalitos crujientes fritos al momento con sal marina y limón. Un emblema de la costa marplatense para disfrutar en la carpa.","category_id":"cat-rabas","price":13500,"cost":4800,"image":"https://images.unsplash.com/photo-1534422298391-e4f8c172dddb?auto=format&fit=crop&w=800&q=80","sku":"MAR-02","is_available":true,"is_active":true,"rating":4.7,"reviews_count":178,"sales_count":42,"prep_time_minutes":10,"tag":"TRADICIONAL","is_veggie":false,"is_gluten_free":false,"included_ingredients":["Cornalitos frescos","Harina de trigo","Limón","Sal marina"],"removable_ingredients":[],"available_addons":[],"variants":[]},{"id":"prod-pizza-napolitana","name":"Pizza Napolitana Fior di Latte","description":"Masa fermentada 48hs con harina orgánica horneada a la piedra, salsa pomodoro San Marzano, mozzarella fior di latte fundida, albahaca fresca y aceite de oliva virgen extra.","category_id":"cat-pizzas","price":13500,"cost":4100,"image":"https://images.unsplash.com/photo-1574071318508-1cdbab80d002?auto=format&fit=crop&w=800&q=80","sku":"PIZ-01","is_available":true,"is_active":true,"rating":4.9,"reviews_count":265,"sales_count":65,"prep_time_minutes":16,"tag":"OPCIÓN VEGGIE","is_veggie":true,"is_gluten_free":false,"included_ingredients":["Pomodoro San Marzano","Mozzarella fior di latte","Rodajas de tomate fresco","Ajo suave","Albahaca fresca"],"removable_ingredients":["Ajo suave","Rodajas de tomate"],"available_addons":[{"id":"add-jamon","name":"Jamón crudo serrano en lonjas","price":3400},{"id":"add-olivas","name":"Aceitunas negras descarozadas","price":1200}],"variants":[]},{"id":"prod-papas-trufadas","name":"Papas Rústicas Trufadas con Parmesano","description":"Papas corte bastón rústico con piel crujiente, queso parmesano reggiano rallado fino, aceite de trufa negra aromático y ciboulette fresco.","category_id":"cat-papas","price":8400,"cost":2300,"image":"https://images.unsplash.com/photo-1573080496219-bb080dd4f877?auto=format&fit=crop&w=800&q=80","sku":"PAP-01","is_available":true,"is_active":true,"rating":4.8,"reviews_count":310,"sales_count":92,"prep_time_minutes":10,"tag":"PARA COMPARTIR","is_veggie":true,"is_gluten_free":false,"included_ingredients":["Papas rústicas","Aceite de trufa","Parmesano reggiano","Ciboulette"],"removable_ingredients":["Ciboulette"],"available_addons":[{"id":"add-dip-cheddar","name":"Pocillo cheddar fundido caliente","price":1600}],"variants":[]},{"id":"prod-papas-cheddar-bacon","name":"Papas Fritas Cheddar & Bacon","description":"Corte grueso con cáscara, abundante salsa de queso cheddar inglés fundido, lluvia de panceta crocante y ciboulette fresco.","category_id":"cat-papas","price":7400,"cost":2100,"image":"https://imag