 tropical","price":900}],"variants":[]},{"id":"prod-licuado-maracuya","name":"Licuado Natural Tropical con Hielo Frappé","description":"Preparado al instante con frutas de estación naturales: Maracuyá, Frutilla, Naranja o Banana, al agua o con leche cremosa.","category_id":"cat-bebidas","price":4800,"cost":1100,"image":"https://images.unsplash.com/photo-1505252585461-04db1eb84625?auto=format&fit=crop&w=800&q=80","sku":"LIC-01","is_available":true,"is_active":true,"rating":4.8,"reviews_count":160,"sales_count":68,"prep_time_minutes":4,"tag":"REFRESCANTE","is_veggie":false,"is_gluten_free":false,"included_ingredients":[],"removable_ingredients":[],"available_addons":[],"variants":[{"id":"v-agua","name":"Al agua con hielo frappé","price":4800},{"id":"v-leche","name":"Con leche cremosa","price":5300},{"id":"v-naranja","name":"Con base de jugo de naranja exprimido","price":5600}]},{"id":"prod-volcan-chocolate","name":"Volcán Tibio de Chocolate con Helado","description":"Corazón tibio y fluido de auténtico chocolate belga 70%, con bocha de helado artesanal de crema americana y hojas de menta.","category_id":"cat-postres","price":6200,"cost":1900,"image":"https://images.unsplash.com/photo-1606313564200-e75d5e30476c?auto=format&fit=crop&w=800&q=80","sku":"POS-01","is_available":true,"is_active":true,"rating":4.9,"reviews_count":230,"sales_count":54,"prep_time_minutes":12,"tag":"POSTRE TIBIO","is_veggie":false,"is_gluten_free":false,"included_ingredients":[],"removable_ingredients":[],"available_addons":[],"variants":[]},{"id":"prod-cafe-espresso","name":"Café Espresso Doble Especialidad","description":"Granos de especialidad origen Colombia tostados en Mar del Plata, notas a cacao y caramelo. Servido con vasito de soda y galletita artesanal.","category_id":"cat-postres","price":3200,"cost":600,"image":"https://images.unsplash.com/photo-1514432324607-a09d9b4aefdd?auto=format&fit=crop&w=800&q=80","sku":"CAF-01","is_available":true,"is_active":true,"rating":4.8,"reviews_count":140,"sales_count":60,"prep_time_minutes":3,"tag":"ESPECIALIDAD","is_veggie":false,"is_gluten_free":false,"included_ingredients":[],"removable_ingredients":[],"available_addons":[],"variants":[]}]'::jsonb) as seed(id text, name text, description text, category_id text, price numeric, cost numeric, image text, sku text, is_available boolean, is_active boolean, rating numeric, reviews_count integer, sales_count integer, prep_time_minutes integer, tag text, is_veggie boolean, is_gluten_free boolean, included_ingredients text[], removable_ingredients text[], available_addons jsonb, variants jsonb)
  on conflict (business_id, id) do nothing;

  insert into public.promotions (
    business_id, id, name, description, promo_price, regular_price, image, badge,
    valid_until, included_product_names, conditions
  )
  select v_business_id, seed.id, seed.name, seed.description, seed.promo_price, seed.regular_price,
         seed.image, seed.badge, seed.valid_until, seed.included_product_names, seed.conditions
  from jsonb_to_recordset('[{"id":"promo-combo-playero","name":"Combo Playero: Doble Bacon + Papas + Pinta IPA","description":"La combinación favorita del mediodía: Doble Bacon Burger completa con porción de papas rústicas y una pinta de cerveza tirada.","promo_price":17900,"regular_price":23400,"image":"https://images.unsplash.com/photo-1594212699903-ec8a3eca50f5?auto=format&fit=crop&w=800&q=80","badge":"AHORRÁ $5.500","valid_until":"2026-12-31","included_product_names":["Doble Bacon Cheddar Burger","Papas Rústicas Trufadas","Cerveza IPA Tirada 500ml"],"conditions":"Válido todos los días en carpas, sombrillas y restaurante. No acumulable."},{"id":"promo-rabas-limonada","name":"Dúo Costa Serena: Rabas Romanas + 2 Licuados","description":"Porción abundante de rabas crocantes del puerto con salsa tártara y 2 licuados naturales a elección para disfrutar a la orilla del mar.","promo_price":22500,"regular_price":26400,"image":"https://images.unsplash.com/photo-1599488615731-7e5c2823ff28?auto=format&fit=crop&w=800&q=80","badge":"IDEAL PARA 2","valid_until":"2026-12-31","included_product_names":["Rabas Tiernas a la Romana","2x Licuados Tropicales"],"conditions":"Disponible de 12:00 a 19:30 hs."},{"id":"promo-sunset-tragos","name":"Sunset Beach 2x1 en Cocktails & Tragos","description":"Disfrutá del atardecer con 2 Mojitos Cubanos o Gin Tonics con frutas al precio de uno.","promo_price":6500,"regular_price":13000,"image":"https://images.unsplash.com/photo-1551024709-8f23befc6f87?auto=format&fit=crop&w=800&q=80","badge":"2x1 ATARDECER","valid_until":"2026-12-31","included_product_names":["2x Mojito Cubano Playa Serena"],"conditions":"Horario especial de 17:30 a 20:00 hs en todos los sectores."}]'::jsonb) as seed(id text, name text, description text, promo_price numeric, regular_price numeric, image text, badge text, valid_until date, included_product_names text[], conditions text)
  on conflict (business_id, id) do nothing;
end;
$demo_seed$;

commit;
